24	// mailparser ships no bundled type declarations and its untyped JS module can't
25	// be augmented via `declare module`. Instead we describe the slice we use with
26	// local interfaces and import `simpleParser` with a suppressed-error import,
27	// exposing a single typed `parseMessage` wrapper for the rest of the backend.
28	// @ts-ignore -- mailparser has no type declarations
29	import { simpleParser as _simpleParser } from "mailparser";
