59	const simpleParser = _simpleParser as (
60	  source: Buffer | string,
61	  options?: Record<string, unknown>,
62	) => Promise<ParsedMessage>;
63	
64	/** Parse a raw RFC822 message source into a typed structure (via mailparser). */
65	export async function parseMessage(source: Buffer | string): Promise<ParsedMessage> {
66	  return simpleParser(source);
67	}
