69	/** The TLS servername the mail server's certificate is issued for. */
70	export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";
71	
72	/** Minimal credential shape needed to authenticate an IMAP/SMTP session. */
73	export type MailboxCredentials = { address: string; password: string };
74	
75	/** The sender identity the customer configured, applied to every outgoing message. */
76	export type MailboxIdentity = {
77	  displayName: string | null;
78	  replyTo: string | null;
79	  organization: string | null;
80	};
