91	/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
92	export type ResolvedMailbox = {
93	  user: User;
94	  mailboxId: string;
95	  address: string;
96	  quotaMB: number | null;
97	  cred: MailboxCredentials;
98	  identity: MailboxIdentity;
99	  subscription: ResolvedSubscription;
100	};
