102	/**
103	 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
104	 *
105	 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
106	 * the mail server — or one whose row was lost — was invisible in the portal even
107	 * though real mail was landing in it ("its not detecting the mailbox that i
108	 * already have on this account"). This reconciles the two.
109	 *
110	 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
111	 * a way to acquire someone else's mailbox:
112	 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
113	 *   2. Only subscriptions with `verified === true` are eligible. Owning a
114	 *      subscription ROW is not proof of owning the DOMAIN — an unverified
115	 *      external subscription is just a claim, and adopting on a claim would
116	 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
117	 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
118	 *      already has a row, so a mailbox another tenant legitimately holds is
119	 *      never re-pointed at this user.
120	 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
121	 *      customer is told to reset it — adoption grants visibility, not access.
122	 *
123	 * Never throws: a Mailcow outage must not turn the mail page into an error.
124	 * Returns the number of rows created.
125	 */
126	export async function discoverMailboxes(userId: string): Promise<number> {
127	  if (!mailcowConfigured()) return 0;
128	
129	  // Guard against hammering Mailcow: the mail page calls this on every load for
130	  // an account with no mailbox, which is exactly the account that reaches here.
131	  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
132	  if (!gate.ok) return 0;
133	
134	  const subs = await db.emailSubscription.findMany({
135	    where: { userId, status: { not: "CANCELLED" }, verified: true },
136	    select: { id: true, domainName: true },
137	  });
138	  if (subs.length === 0) return 0;
139	
140	  let created = 0;
141	  for (const sub of subs) {
142	    const domain = sub.domainName.trim().toLowerCase();
143	    if (!domain) continue;
144	
145	    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
146	    try {
147	      remote = await mcListMailboxes(domain);
148	    } catch (e) {
149	      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
150	      continue;
151	    }
152	    if (remote.length === 0) continue;
153	
154	    const existing = await db.mailbox.findMany({
155	      where: { address: { in: remote.map((m) => m.address) } },
156	      select: { address: true },
157	    });
158	    const known = new Set(existing.map((m) => m.address.toLowerCase()));
159	
160	    for (const m of remote) {
161	      if (known.has(m.address)) continue;
162	      try {
163	        await db.mailbox.create({
164	          data: {
165	            subscriptionId: sub.id,
166	            address: m.address,
167	            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
168	            status: m.active ? "ACTIVE" : "SUSPENDED",
169	            displayName: m.name && m.name !== m.address ? m.name : null,
170	          },
171	        });
172	        created++;
173	      } catch {
174	        // Unique-violation race (two tabs discovering at once) — the row exists
175	        // now either way, which is the outcome we wanted.
176	      }
177	    }
178	  }
179	
180	  if (created > 0) {
181	    await db.auditLog
182	      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
183	      .catch(() => {});
184	  }
185	  return created;
186	}
