188	/**
189	 * Why the caller can't open webmail, so the UI can say what is actually wrong
190	 * instead of one catch-all "No mailbox connected".
191	 */
192	export type MailAccessState =
193	  | { kind: "ok"; address: string }
194	  | { kind: "no-subscription" }
195	  | { kind: "unverified-domain"; domains: string[] }
196	  | { kind: "no-mailbox"; domains: string[] }
197	  | { kind: "no-password"; address: string }
198	  | { kind: "server-unreachable"; address: string };
199	
200	/**
201	 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
202	 * that only exists on the server is found before we declare there is none.
203	 */
204	export async function mailAccessState(userId: string): Promise<MailAccessState> {
205	  await discoverMailboxes(userId).catch(() => 0);
206	
207	  const subs = await db.emailSubscription.findMany({
208	    where: { userId, status: { not: "CANCELLED" } },
209	    select: { domainName: true, verified: true, external: true },
210	  });
211	  if (subs.length === 0) return { kind: "no-subscription" };
212	
213	  const boxes = await db.mailbox.findMany({
214	    where: { subscription: { userId } },
215	    orderBy: { createdAt: "asc" },
216	    select: { address: true, passwordEnc: true },
217	  });
218	
219	  if (boxes.length === 0) {
220	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
221	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
222	    // An unverified domain is the more actionable problem: no mailbox can even
223	    // be created on it yet, so lead with that.
224	    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
225	    return { kind: "no-mailbox", domains: verified };
226	  }
227	
228	  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
229	  if (!withPassword) return { kind: "no-password", address: boxes[0].address };
230	
231	  // A mailbox and a credential exist, so the page's failure was the mail server
232	  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
233	  return { kind: "server-unreachable", address: withPassword.address };
234	}
235	
236	/**
237	 * Resolve the mailbox a request may act on. Requires an authenticated user,
238	 * loads only mailboxes belonging to that user's email subscriptions, and (when
239	 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
240	 * credential; throws a friendly error if the password was never captured.
241	 *
242	 * NEVER returns a mailbox the caller does not own.
243	 */
244	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
245	  const user = await requireUser();
246	  const load = () =>
247	    db.mailbox.findMany({
248	      where: { subscription: { userId: user.id } },
249	      include: { subscription: true },
250	      orderBy: { createdAt: "asc" },
251	    });
252	
253	  let boxes = await load();
254	  const wanted = mailboxAddress?.trim().toLowerCase();
255	
256	  // A miss here used to be terminal, which is how a mailbox that exists on the
257	  // mail server but has no local row became "you do not have a mailbox yet".
258	  // Reconcile against Mailcow (verified domains only) before giving that answer.
259	  if (boxes.length === 0 || (wanted && !boxes.some((b) => b.address.toLowerCase() === wanted))) {
260	    if (await discoverMailboxes(user.id).catch(() => 0)) boxes = await load();
261	  }
262	
263	  if (boxes.length === 0) {
264	    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
265	  }
266	
267	  let box = boxes[0];
268	  if (wanted) {
269	    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
270	    if (!match) throw new Error("You do not have access to that mailbox.");
271	    box = match;
272	  }
273	
274	  const password = decryptSecret(box.passwordEnc);
275	  if (!password) {
276	    throw new Error("Please reset your mailbox password first to enable webmail access.");
277	  }
278	
279	  return {
280	    user,
281	    mailboxId: box.id,
282	    address: box.address,
283	    quotaMB: box.quotaMB ?? null,
284	    cred: { address: box.address, password },
285	    identity: {
286	      displayName: box.displayName,
287	      replyTo: box.replyTo,
288	      organization: box.organization,
289	    },
290	    subscription: {
291	      id: box.subscription.id,
292	      domainName: box.subscription.domainName,
293	      external: box.subscription.external,
294	      verified: box.subscription.verified,
295	      status: box.subscription.status,
296	    },
297	  };
298	}
