300	/** Build a per-request imapflow client for the given credential. */
301	export function createImapClient(cred: MailboxCredentials): ImapFlow {
302	  return new ImapFlow({
303	    host: MAIL_IMAP_HOST,
304	    port: MAIL_IMAP_PORT,
305	    secure: true,
306	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
307	    // and validation servername so TLS verifies against the right name.
308	    servername: MAIL_TLS_SERVERNAME,
309	    tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
310	    auth: { user: cred.address, pass: cred.password },
311	    logger: false,
312	    disableAutoIdle: true,
313	  });
314	}
315	
316	/**
317	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
318	 * logout, falling back to a hard close). Suitable for one operation per request.
319	 */
320	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
321	  const client = createImapClient(cred);
322	  await client.connect();
323	  try {
324	    return await fn(client);
325	  } finally {
326	    try {
327	      await client.logout();
328	    } catch {
329	      try {
330	        client.close();
331	      } catch {
332	        /* already gone */
333	      }
334	    }
335	  }
336	}
337	
338	/**
339	 * Like `withImap` but also selects `path` under a mailbox lock (released before
340	 * the connection closes). Use for any op that fetches/searches/mutates messages.
341	 */
342	export async function withMailbox<T>(
343	  cred: MailboxCredentials,
344	  path: string,
345	  fn: (client: ImapFlow) => Promise<T>,
346	  opts?: { readOnly?: boolean },
347	): Promise<T> {
348	  return withImap(cred, async (client) => {
349	    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
350	    const lock = await client.getMailboxLock(path, lockOpts);
351	    try {
352	      return await fn(client);
353	    } finally {
354	      lock.release();
355	    }
356	  });
357	}
