359	/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
360	export function folderRole(path: string, specialUse?: string): MailFolderRole {
361	  const su = (specialUse || "").toLowerCase();
362	  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
363	  switch (su) {
364	    case "\\sent":
365	      return "sent";
366	    case "\\drafts":
367	      return "drafts";
368	    case "\\trash":
369	      return "trash";
370	    case "\\junk":
371	      return "junk";
372	    case "\\archive":
373	    case "\\all":
374	      return "archive";
375	  }
376	  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
377	  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
378	  if (leaf === "inbox") return "inbox";
379	  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
380	  if (["drafts", "draft"].includes(leaf)) return "drafts";
381	  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
382	  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
383	  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
384	  return "custom";
385	}
386	
387	/** Convert an imapflow envelope address to our MailAddress shape. */
388	export function toMailAddress(a: MessageAddressObject | undefined): MailAddress {
389	  return { name: a?.name || undefined, address: a?.address || "" };
390	}
391	
392	/** Convert an array of imapflow envelope addresses to MailAddress[]. */
393	export function toMailAddresses(list: MessageAddressObject[] | undefined): MailAddress[] {
394	  return (list || []).map(toMailAddress).filter((a) => a.address);
395	}
396	
397	/**
398	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
399	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
400	 * "1" for a simple single-part message (whose structure carries no part id).
401	 */
402	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
403	  if (!structure) return { part: "1", isHtml: false };
404	  const leaves: MessageStructureObject[] = [];
405	  const walk = (node: MessageStructureObject) => {
406	    if (node.childNodes && node.childNodes.length) {
407	      node.childNodes.forEach(walk);
408	    } else {
409	      leaves.push(node);
410	    }
411	  };
412	  walk(structure);
413	
414	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
415	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
416	  if (plain) return { part: plain.part || "1", isHtml: false };
417	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
418	  if (html) return { part: html.part || "1", isHtml: true };
419	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
420	}
421	
422	/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
423	export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
424	  if (!structure) return false;
425	  let found = false;
426	  const walk = (node: MessageStructureObject) => {
427	    const type = (node.type || "").toLowerCase();
428	    const disp = (node.disposition || "").toLowerCase();
429	    if (node.childNodes && node.childNodes.length) {
430	      node.childNodes.forEach(walk);
431	      return;
432	    }
433	    if (disp === "attachment") found = true;
434	    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
435	  };
436	  walk(structure);
437	  return found;
438	}
