440	/** Read imapflow message flags into the summary booleans. */
441	export function readFlags(flags: Set<string> | undefined): { seen: boolean; flagged: boolean; answered: boolean } {
442	  const f = flags ?? new Set<string>();
443	  return { seen: f.has("\\Seen"), flagged: f.has("\\Flagged"), answered: f.has("\\Answered") };
444	}
445	
446	/** Best-effort ISO date string from an imapflow fetch result. */
447	export function isoDate(msg: Pick<FetchMessageObject, "envelope" | "internalDate">): string {
448	  const d = msg.envelope?.date || (msg.internalDate ? new Date(msg.internalDate) : undefined);
449	  const date = d instanceof Date ? d : d ? new Date(d) : new Date(0);
450	  return Number.isNaN(date.getTime()) ? new Date(0).toISOString() : date.toISOString();
451	}
