56	// ---------------------------------------------------------------------------
57	// Mailboxes
58	// ---------------------------------------------------------------------------
59	
60	/** The signed-in user's mailboxes with used/quota bytes (best effort per box). */
61	export async function getMailboxes(): Promise<MailboxInfo[]> {
62	  const user = await requireUser();
63	  const boxes = await db.mailbox.findMany({
64	    where: { subscription: { userId: user.id } },
65	    include: { subscription: true },
66	    orderBy: { createdAt: "asc" },
67	  });
68	
69	  const out: MailboxInfo[] = [];
70	  for (const box of boxes) {
71	    const quotaBytes = box.quotaMB ? box.quotaMB * 1024 * 1024 : 0;
72	    const password = decryptSecret(box.passwordEnc);
73	    let usedBytes = 0;
74	    let liveQuota = quotaBytes;
75	    if (password) {
76	      try {
77	        const q = await withImap({ address: box.address, password }, async (client) => {
78	          const quota = await client.getQuota().catch(() => false as const);
79	          if (quota && quota.storage) return quota.storage;
80	          // Fall back to STATUS SIZE on INBOX where QUOTA isn't advertised.
81	          const st = await client.status("INBOX", { size: true }).catch(() => null);
82	          return st?.size != null ? { used: st.size, limit: quotaBytes } : null;
83	        });
84	        if (q) {
85	          usedBytes = q.used ?? 0;
86	          if (q.limit && q.limit > 0) liveQuota = q.limit;
87	        }
88	      } catch {
89	        /* connection/auth issue — report zero usage rather than failing the page */
90	      }
91	    }
92	    out.push({ address: box.address, usedBytes, quotaBytes: liveQuota });
93	  }
94	  return out;
95	}
