520	/** Set or clear the \Seen or \Flagged flag on a message. */
521	export async function setFlag(
522	  folder: string,
523	  uid: number,
524	  flag: "seen" | "flagged",
525	  value: boolean,
526	  mailboxAddress?: string,
527	): Promise<void> {
