551	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
552	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
553	  const { user, cred } = await resolveMailbox(mailboxAddress);
554	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
555	
556	  await withImap(cred, async (client) => {
557	    // Determine the Trash folder path.
558	    let trashPath = "Trash";
559	    try {
560	      const list = await client.list();
561	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
562	      if (trash) trashPath = trash.path;
563	    } catch {
564	      /* fall back to "Trash" */
565	    }
566	
567	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
568	    const lock = await client.getMailboxLock(folder);
569	    try {
570	      if (inTrash) {
571	        await client.messageDelete(String(uid), { uid: true });
572	      } else {
573	        await client.messageMove(String(uid), trashPath, { uid: true });
574	      }
575	    } finally {
576	      lock.release();
577	    }
578	  });
579	}
