1	// Shared contract for the native Nxeon mail client (/dashboard/mail).
2	// Both the IMAP/SMTP backend (lib/mail/*, lib/actions-mail.ts) and the UI
3	// (components/customer/mail/*, app/dashboard/mail) build against these types so
4	// they can't drift. The client connects to the customer's own mailbox on the
5	// self-hosted mail server (10.20.0.10) over IMAP (993) / SMTP submission (587),
6	// authenticating with the mailbox's stored (encrypted) credential.
7	
8	export const MAIL_IMAP_HOST = process.env.MAIL_IMAP_HOST || "10.20.0.10";
9	export const MAIL_IMAP_PORT = Number(process.env.MAIL_IMAP_PORT || 993);
10	export const MAIL_SMTP_HOST = process.env.MAIL_SMTP_HOST || "10.20.0.10";
11	export const MAIL_SMTP_PORT = Number(process.env.MAIL_SMTP_PORT || 587);
12	
13	export type MailFolderRole =
14	  | "inbox" | "sent" | "drafts" | "trash" | "junk" | "archive" | "custom";
15	
16	export type MailFolder = {
17	  path: string; // IMAP path, e.g. "INBOX", "Sent"
18	  name: string; // display name
19	  role: MailFolderRole;
20	  unread: number;
21	  total: number;
22	};
23	
24	export type MailAddress = { name?: string; address: string };
25	
26	export type MessageSummary = {
27	  uid: number;
28	  folder: string;
29	  from: MailAddress;
30	  to: MailAddress[];
31	  subject: string;
32	  preview: string; // short text snippet of the body
33	  date: string; // ISO
34	  seen: boolean;
35	  flagged: boolean; // starred
36	  answered: boolean;
37	  hasAttachments: boolean;
38	};
