1	// Sieve compiler for the customer-facing mailbox rules (auto-reply + forwarding).
2	//
3	// Plain server-side module (NO "use server"): pure string building, no I/O. The
4	// caller (lib/actions-mailbox-settings.ts) pushes the result to Mailcow.
5	//
6	// WHY this file exists: auto-reply and forwarding were STORE-ONLY. The panel
7	// said "saved", nothing on the mail server changed, and a customer who switched
8	// on an out-of-office before a holiday got no auto-replies and no forwarded mail
9	// at all. Mailcow's REST API does expose per-mailbox sieve filters, and the
10	// self-hosted Dovecot has the extensions we need — verified read-only against
11	// the live server and against mailcow's own config:
12	//
13	//   sieve_extensions = +notify +imapflags +vacation-seconds +editheader
14	//   sieve_vacation_send_from_recipient = yes   (auto-reply is From: the mailbox)
15	//   sieve_redirect_envelope_from = recipient
16	//
17	// `vacation`, `copy`, `date` and `relational` are all in Pigeonhole's default
18	// extension set AND in mailcow's PHP sieve validator
19	// (data/web/inc/lib/sieve/extensions/*.xml), which rejects the whole API call if
20	// a `require` names something it doesn't know. Only those four are used here.
21	//
22	// Everything is compiled into ONE script because Mailcow keeps at most one
23	// ACTIVE filter per (mailbox, filter_type) — adding a second active filter
24	// silently deactivates the first, which would make enabling forwarding turn the
25	// customer's auto-reply back off.
26	
27	/** The rule state we compile from — the persisted Mailbox columns, verbatim. */
28	export type MailboxRuleState = {
29	  address: string;
30	  autoReplyEnabled: boolean;
31	  autoReplySubject: string | null;
32	  autoReplyBody: string | null;
33	  autoReplyStart: Date | null;
34	  autoReplyEnd: Date | null;
35	  forwardingAddress: string | null;
36	  forwardKeepCopy: boolean;
37	};
38	
39	/**
40	 * `script_desc` we tag our filter with. This is the ONLY thing that identifies a
41	 * script as ours, so the sync path never edits or deletes a filter a customer
42	 * (or an operator) created by hand in Mailcow's own UI.
43	 */
44	export const NXEON_SIEVE_DESC = "Nxeon mailbox settings (managed — do not edit)";
45	
46	/**
47	 * Mailcow's `prefilter` maps to Dovecot `sieve_before`, so these rules run ahead
48	 * of the mailbox's own personal script. Forwarding and out-of-office must not be
49	 * defeated by a later "file everything into a folder" rule.
50	 */
51	export const NXEON_SIEVE_TYPE = "prefilter" as const;
52	
53	// Markers so the live script can be read back and reported honestly in the UI
54	// without re-parsing sieve. `getMailRuleStatus` looks for exactly these.
55	export const MARK_AUTOREPLY = "# nxeon:autoreply";
56	export const MARK_FORWARD = "# nxeon:forward";
57	
58	/**
59	 * Quote a value as a sieve quoted-string (RFC 5228 §2.4.2).
60	 *
61	 * Backslash first, then the quote character — reversing the order would
62	 * double-escape. Control characters are dropped rather than escaped: sieve has
63	 * no escape form for them, and a stray NUL or ESC in the body would make
64	 * Mailcow's validator reject the entire save. CRLF is legal inside a quoted
65	 * string, so multi-line auto-reply bodies survive intact.
66	 */
67	function sq(value: string): string {
68	  const cleaned = value
69	    // eslint-disable-next-line no-control-regex
70	    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
71	    .replace(/\r\n|\r|\n/g, "\n");
72	  const escaped = cleaned.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\r\n");
73	  return `"${escaped}"`;
74	}
75	
76	/** Format a Date as the `YYYY-MM-DD` string sieve's `date`/`"date"` part yields. */
77	function isoDay(d: Date): string {
78	  return d.toISOString().slice(0, 10);
79	}
80	
81	/**
82	 * Compile the mailbox's rules into a sieve script, or return "" when the
83	 * customer has nothing enabled (the caller then DELETES the managed filter, so
84	 * turning a rule off really turns it off on the server).
85	 */
86	export function buildMailboxSieve(state: MailboxRuleState): string {
87	  const requires = new Set<string>();
88	  const body: string[] = [];
89	
90	  const autoReplyBody = (state.autoReplyBody ?? "").trim();
91	  const autoReplyOn = state.autoReplyEnabled && autoReplyBody.length > 0;
92	  const forwardTo = (state.forwardingAddress ?? "").trim().toLowerCase();
93	  const forwardOn = forwardTo.length > 0;
94	
95	  if (autoReplyOn) {
96	    requires.add("vacation");
97	
98	    // `:days 1` is Pigeonhole's dedupe window: one auto-reply per sender per day,
99	    // so a mailing list or a retrying sender can't be answered in a loop.
100	    const args = [":days 1", `:addresses [${sq(state.address)}]`];
101	    const subject = (state.autoReplySubject ?? "").trim();
102	    // An empty `:subject` is invalid; omitting it lets Pigeonhole use
103	    // "Auto: <original subject>", which is better than a blank Subject header.
104	    if (subject) args.push(`:subject ${sq(subject)}`);
105	    const vacation = `vacation ${args.join(" ")} ${sq(autoReplyBody)};`;
106	
107	    // The date window is enforced ON THE SERVER, not by us flipping a flag on a
108	    // schedule — nothing in this codebase runs a job to re-push sieve at
109	    // midnight, so a client-side window would have kept replying forever.
110	    const guards: string[] = [];
111	    if (state.autoReplyStart) guards.push(`currentdate :value "ge" "date" ${sq(isoDay(state.autoReplyStart))}`);
112	    if (state.autoReplyEnd) guards.push(`currentdate :value "le" "date" ${sq(isoDay(state.autoReplyEnd))}`);
113	
114	    body.push(MARK_AUTOREPLY);
115	    if (guards.length === 0) {
116	      body.push(vacation);
117	    } else {
118	      requires.add("date");
119	      requires.add("relational");
120	      // Kept on one line on purpose: the script is joined with CRLF below, so an
121	      // embedded "\n" here would leave a bare LF in the middle of a statement.
122	      const test = guards.length === 1 ? guards[0] : `allof (${guards.join(", ")})`;
123	      body.push(`if ${test}`, "{", `  ${vacation}`, "}");
124	    }
125	  }
126	
127	  if (forwardOn) {
128	    body.push("", MARK_FORWARD);
129	    if (state.forwardKeepCopy) {
130	      // `redirect :copy` leaves the implicit keep intact, so the message is both
131	      // forwarded and delivered here.
132	      requires.add("copy");
133	      body.push(`redirect :copy ${sq(forwardTo)};`);
134	    } else {
135	      // A bare `redirect` cancels the implicit keep; `stop` ends the script chain
136	      // so no later script in the sequence can re-introduce a local delivery.
137	      body.push(`redirect ${sq(forwardTo)};`, "stop;");
138	    }
139	  }
140	
141	  if (body.length === 0) return "";
142	
143	  const header = [
144	    "# Generated by Nxeon from your mailbox settings. Changes here are overwritten.",
145	    `# Mailbox: ${state.address.replace(/[\r\n]/g, "")}`,
146	  ];
147	  const requireLine =
148	    requires.size > 0 ? `require [${[...requires].sort().map((r) => sq(r)).join(", ")}];` : "";
149	
150	  return [...header, requireLine, "", ...body]
151	    .filter((line, i, all) => !(line === "" && all[i - 1] === "")) // no double blanks
152	    .join("\r\n")
153	    .concat("\r\n");
154	}
155	
156	/** True when the live script on the server is one we generated. */
157	export function isNxeonSieve(scriptDesc: string): boolean {
158	  return scriptDesc.trim() === NXEON_SIEVE_DESC;
159	}
