33	const ENTITY_MAP: Record<string, string> = {
34	  "&nbsp;": " ",
35	  "&amp;": "&",
36	  "&lt;": "<",
37	  "&gt;": ">",
38	  "&quot;": '"',
39	  "&#39;": "'",
40	  "&apos;": "'",
41	  "&mdash;": "—",
42	  "&ndash;": "–",
43	  "&hellip;": "…",
44	};
45	
46	/**
47	 * Derive a readable plain-text version of a (sanitized) HTML signature, for the
48	 * text/plain MIME part and as the legacy `signature` fallback. Turns block
49	 * boundaries and <br> into newlines, list items into "• ", <hr> into a rule,
50	 * strips remaining tags and decodes the common entities. Never throws.
51	 */
52	export function signatureHtmlToText(html: string | null | undefined): string {
53	  if (!html) return "";
54	  let t = String(html);
55	  t = t.replace(/<\s*br\s*\/?\s*>/gi, "\n");
56	  t = t.replace(/<\s*hr[^>]*>/gi, "\n----------\n");
57	  t = t.replace(/<\s*li[^>]*>/gi, "• ");
58	  t = t.replace(/<\/\s*(p|div|li|h[1-6]|tr|ul|ol)\s*>/gi, "\n");
59	  t = t.replace(/<[^>]+>/g, "");
60	  t = t.replace(/&(?:nbsp|amp|lt|gt|quot|#39|apos|mdash|ndash|hellip);/gi, (m) => ENTITY_MAP[m.toLowerCase()] ?? ENTITY_MAP[m] ?? m);
61	  t = t.replace(/&#x([0-9a-f]+);/gi, (_, h) => codePoint(parseInt(h, 16)));
62	  t = t.replace(/&#(\d+);/g, (_, d) => codePoint(parseInt(d, 10)));
63	  // Tidy whitespace.
64	  t = t.replace(/\r/g, "");
65	  t = t.replace(/[ \t]+\n/g, "\n");
66	  t = t.replace(/\n{3,}/g, "\n\n");
67	  return t.trim();
68	}
69	
70	function codePoint(n: number): string {
71	  if (!Number.isFinite(n) || n < 0 || n > 0x10ffff) return "";
72	  try {
73	    return String.fromCodePoint(n);
74	  } catch {
75	    return "";
76	  }
77	}
78	
79	/** Escape user text for safe interpolation into signature HTML templates. */
80	function esc(s: string): string {
81	  return s
82	    .replace(/&/g, "&amp;")
83	    .replace(/</g, "&lt;")
84	    .replace(/>/g, "&gt;");
85	}
