83	/** Format a stored Date as a `YYYY-MM-DD` string (or "" when null). */
84	function toDateInput(d: Date | null | undefined): string {
85	  if (!d) return "";
86	  try {
87	    return d.toISOString().slice(0, 10);
88	  } catch {
89	    return "";
90	  }
