93	/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
94	function fromDateInput(s: string | null | undefined): Date | null {
95	  const v = (s ?? "").trim();
96	  if (!v) return null;
97	  const d = new Date(`${v}T00:00:00.000Z`);
98	  return Number.isNaN(d.getTime()) ? null : d;
