101	/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
102	function gate(key: string, max: number, windowMs: number): Result | null {
103	  const r = checkRateLimit(key, { max, windowMs });
104	  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
