156	/**
157	 * Save identity + signature onto the mailbox row. Only the fields actually
158	 * present in `input` are written, so the Identity and Signature sub-forms can
159	 * each save independently without clobbering the other's data.
160	 *
161	 * Signature HTML is sanitised server-side with `safeHtml` (defence in depth —
162	 * the client sanitises too) and a plain-text version is derived into the legacy
163	 * `signature` column so the text/plain MIME part always has a fallback.
164	 */
165	export async function saveMailboxSettings(
166	  input: {
167	    displayName?: string;
168	    replyTo?: string;
169	    organization?: string;
170	    signatureHtml?: string;
171	    signatureEnabled?: boolean;
172	    signatureOnReply?: boolean;
173	    signaturePlacement?: string;
174	  },
175	  mailboxAddress?: string,
176	): Promise<Result> {
177	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
178	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
179	  if (limited) return limited;
180	
181	  const data: {
182	    displayName?: string | null;
183	    replyTo?: string | null;
184	    organization?: string | null;
185	    signatureHtml?: string | null;
186	    signature?: string | null;
187	    signatureEnabled?: boolean;
188	    signatureOnReply?: boolean;
189	    signaturePlacement?: string;
190	  } = {};
191	
192	  if (input.displayName !== undefined) {
193	    const displayName = input.displayName.trim();
194	    if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
195	    data.displayName = displayName || null;
196	  }
197	
198	  if (input.replyTo !== undefined) {
199	    const replyTo = input.replyTo.trim();
200	    if (replyTo && !EMAIL_RE.test(replyTo)) return { ok: false, error: "Reply-to must be a valid email address." };
201	    data.replyTo = replyTo || null;
202	  }
203	
204	  if (input.organization !== undefined) {
205	    const organization = input.organization.trim();
206	    if (organization.length > 200) return { ok: false, error: "Organization is too long (max 200 characters)." };
207	    data.organization = organization || null;
208	  }
209	
210	  if (input.signatureHtml !== undefined) {
211	    const clean = safeHtml(input.signatureHtml);
212	    if (clean.length > SIGNATURE_HTML_MAX) {
213	      return { ok: false, error: "Signature is too long. Please shorten it." };
214	    }
215	    data.signatureHtml = clean || null;
216	    const plain = signatureHtmlToText(clean);
217	    data.signature = plain ? plain : null;
218	  }
219	
220	  if (input.signatureEnabled !== undefined) data.signatureEnabled = Boolean(input.signatureEnabled);
221	  if (input.signatureOnReply !== undefined) data.signatureOnReply = Boolean(input.signatureOnReply);
222	  if (input.signaturePlacement !== undefined) {
223	    data.signaturePlacement = input.signaturePlacement === "above" ? "above" : "below";
224	  }
225	
226	  if (Object.keys(data).length > 0) {
227	    await db.mailbox.update({ where: { id: mailboxId }, data });
228	  }
229	  return { ok: true };
230	}
