285	/**
286	 * Push `state` to Mailcow as the mailbox's single managed sieve filter.
287	 *
288	 * Idempotent: reuses our existing filter when there is one, prunes duplicates
289	 * left by an interrupted save, and DELETES the filter when nothing is enabled so
290	 * switching a rule off really switches it off on the server.
291	 *
292	 * Only ever touches a filter whose `script_desc` is ours — a filter an operator
293	 * created by hand in Mailcow's own UI is left completely alone.
294	 *
295	 * Throws on failure; callers translate that into a user-visible error and skip
296	 * the DB write.
297	 */
298	async function pushMailboxSieve(state: MailboxRuleState): Promise<void> {
299	  const script = buildMailboxSieve(state);
300	  const existing = (await mcListFilters(state.address)).filter((f) => isNxeonSieve(f.scriptDesc));
301	
302	  if (!script) {
303	    for (const f of existing) await mcDeleteFilter(f.id);
304	    return;
305	  }
306	
307	  const [keep, ...duplicates] = existing;
308	  for (const f of duplicates) await mcDeleteFilter(f.id);
309	
310	  if (keep) {
311	    await mcEditFilter(keep.id, {
312	      scriptDesc: NXEON_SIEVE_DESC,
313	      scriptData: script,
314	      filterType: NXEON_SIEVE_TYPE,
315	      active: true,
316	    });
317	  } else {
318	    await mcAddFilter({
319	      address: state.address,
320	      scriptDesc: NXEON_SIEVE_DESC,
321	      scriptData: script,
322	      filterType: NXEON_SIEVE_TYPE,
323	      active: true,
324	    });
325	  }
326	}
