328	/**
329	 * Guard shared by both rule savers.
330	 *
331	 * A sieve `redirect` sends a copy of every inbound message somewhere else, so
332	 * this is exactly the primitive a cross-tenant takeover would want. Owning the
333	 * subscription ROW is not proof of owning the DOMAIN (the 2026-07-25 finding),
334	 * so an unverified external domain is refused outright.
335	 */
336	function assertRulesAllowed(sub: {
337	  external: boolean;
338	  verified: boolean;
339	  status: string;
340	}): { ok: false; error: string } | null {
341	  if (!mailcowConfigured()) {
342	    return { ok: false, error: "Mail server is not configured yet — rules can't be applied." };
343	  }
344	  if (sub.status === "CANCELLED") {
345	    return { ok: false, error: "This subscription is cancelled." };
346	  }
347	  if (sub.external && !sub.verified) {
348	    return {
349	      ok: false,
350	      error: "Verify this domain first (Business Email → Verify DNS) before setting up mail rules.",
351	    };
352	  }
353	  return null;
354	}
