540	/**
541	 * Add an alias on a domain the caller owns. `alias` may be a full address or a
542	 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
543	 * mailbox itself.
544	 */
545	export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
546	  const { user, address } = await resolveMailbox(mailboxAddress);
547	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
548	  if (limited) return limited;
549	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
550	
551	  let aliasAddr = (alias ?? "").trim().toLowerCase();
552	  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
553	  // Accept a bare local part — assume the mailbox's own domain.
554	  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
555	  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };
556	
557	  const owned = await ownedDomains(user.id);
558	  if (!owned.has(domainOf(aliasAddr))) {
559	    return { ok: false, error: "You can only add aliases on a domain you own." };
560	  }
561	
562	  const dest = (goto ?? "").trim() || address;
563	  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
564	  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };
565	
566	  try {
567	    await mcAddAlias(aliasAddr, dest);
568	    return { ok: true };
569	  } catch (e) {
570	    return { ok: false, error: friendly(e) };
571	  }
572	}
