574	/** Remove an alias by id, after verifying it lives on a domain the caller owns. */
575	export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
576	  const { user, address } = await resolveMailbox(mailboxAddress);
577	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
578	  if (limited) return limited;
579	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
580	  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };
581	
582	  const domain = domainOf(address);
583	  const owned = await ownedDomains(user.id);
584	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain." };
585	
586	  try {
587	    // Confirm the alias belongs to this owned domain before deleting.
588	    const list = await mcListAliases(domain);
589	    const match = list.find((a) => a.id === id);
590	    if (!match) return { ok: false, error: "That alias no longer exists on your domain." };
591	    await mcDeleteAlias(id);
592	    return { ok: true };
593	  } catch (e) {
594	    return { ok: false, error: friendly(e) };
595	  }
596	}
