10	import { DAVClient } from "tsdav";
11	import type { DAVCalendar, DAVCalendarObject } from "tsdav";
12	import { CALDAV_BASE } from "./types";
13	import type { MailboxCredentials } from "@/lib/mail/imap";
14	
15	// ---------------------------------------------------------------------------
16	// TLS to an internal IP
17	// ---------------------------------------------------------------------------
18	//
19	// SOGo's certificate is issued for `mail.nxeon.cloud`, but we reach the server
20	// by its internal address (https://10.20.0.10/SOGo/dav). Verifying the cert
21	// against the IP would always fail the hostname check, so — exactly like the
22	// IMAP/SMTP engine (lib/mail/imap.ts) — we disable verification for this
23	// internal hop while still sending the correct SNI `servername` so the reverse
24	// proxy in front of SOGo selects the right vhost/certificate.
25	//
26	// We connect via the mail HOSTNAME (mail.nxeon.cloud) so its TLS cert validates
27	// normally — no custom dispatcher needed. A standalone-`undici` Agent dispatcher is
28	// NOT honoured by Node's built-in fetch and throws "fetch failed", which is why the
29	// earlier internal-IP + dispatcher approach broke the calendar.
30	
31	// ---------------------------------------------------------------------------
32	// Errors
33	// ---------------------------------------------------------------------------
34	
35	/** Normalise any CalDAV/transport failure into a short, user-safe message. */
36	export function caldavError(e: unknown): Error {
37	  const msg = String((e as Error)?.message ?? e ?? "Unknown error");
38	  // Never leak credentials or raw stack detail to the client.
39	  return new Error(`Calendar server error: ${msg.slice(0, 200)}`);
40	}
41	
42	// ---------------------------------------------------------------------------
43	// Client factory
44	// ---------------------------------------------------------------------------
45	
46	/**
47	 * Build a logged-in tsdav DAVClient for the given mailbox credential. Login runs
48	 * CalDAV service discovery (principal + calendar-home) so `fetchCalendars` works.
49	 * Throws a clean `caldavError` on any connection/auth failure.
50	 */
51	export async function caldavClient(cred: MailboxCredentials): Promise<DAVClient> {
52	  try {
53	    const client = new DAVClient({
54	      serverUrl: CALDAV_BASE,
55	      credentials: { username: cred.address, password: cred.password },
56	      authMethod: "Basic",
57	      defaultAccountType: "caldav",
58	    });
59	    await client.login();
60	    return client;
61	  } catch (e) {
62	    throw caldavError(e);
63	  }
64	}
65	
66	// ---------------------------------------------------------------------------
67	// Reads
68	// ---------------------------------------------------------------------------
69	
70	/** All calendar collections in the account (events + tasks live here). */
71	export async function fetchCalendars(client: DAVClient): Promise<DAVCalendar[]> {
72	  try {
73	    return await client.fetchCalendars();
74	  } catch (e) {
75	    throw caldavError(e);
76	  }
77	}
