79	/**
80	 * Fetch the VEVENT objects of a calendar that overlap [startISO, endISO).
81	 * Uses the default VEVENT comp-filter with a server-side time-range so we never
82	 * download the whole collection.
83	 */
84	export async function fetchEventObjects(
85	  client: DAVClient,
86	  calendar: DAVCalendar,
87	  startISO: string,
88	  endISO: string,
89	): Promise<DAVCalendarObject[]> {
90	  try {
91	    return await client.fetchCalendarObjects({
92	      calendar,
93	      timeRange: { start: startISO, end: endISO },
94	    });
95	  } catch (e) {
96	    throw caldavError(e);
97	  }
98	}
99	
100	/**
101	 * Fetch the VTODO objects of a calendar. Time-range filtering on VTODO is poorly
102	 * supported across servers, so we request an explicit VTODO comp-filter and let
103	 * the caller parse them (tasks are few relative to events).
104	 */
105	export async function fetchTaskObjects(
106	  client: DAVClient,
107	  calendar: DAVCalendar,
108	): Promise<DAVCalendarObject[]> {
109	  try {
110	    return await client.fetchCalendarObjects({
111	      calendar,
112	      filters: [
113	        {
114	          "comp-filter": {
115	            _attributes: { name: "VCALENDAR" },
116	            "comp-filter": { _attributes: { name: "VTODO" } },
117	          },
118	        },
119	      ],
120	    });
121	  } catch (e) {
122	    throw caldavError(e);
123	  }
124	}
125	
126	/** Fetch a single calendar object by its href (returns null if absent). */
127	export async function fetchObjectByUrl(
128	  client: DAVClient,
129	  calendar: DAVCalendar,
130	  url: string,
131	): Promise<DAVCalendarObject | null> {
132	  try {
133	    const objs = await client.fetchCalendarObjects({ calendar, objectUrls: [url] });
134	    return objs[0] ?? null;
135	  } catch (e) {
136	    throw caldavError(e);
137	  }
138	}
