140	// ---------------------------------------------------------------------------
141	// Writes
142	// ---------------------------------------------------------------------------
143	
144	/** Ensure a collection URL ends with a single trailing slash. */
145	function withTrailingSlash(url: string): string {
146	  return url.endsWith("/") ? url : `${url}/`;
147	}
148	
149	/** The absolute href a new object with `filename` will occupy under a calendar. */
150	export function objectUrlFor(calendarUrl: string, filename: string): string {
151	  return new URL(filename, withTrailingSlash(calendarUrl)).href;
152	}
153	
154	/**
155	 * PUT a new .ics object into a calendar. Returns the created object's absolute
156	 * href (used as the stable id for later update/delete).
157	 */
158	export async function putObject(
159	  client: DAVClient,
160	  calendarUrl: string,
161	  filename: string,
162	  iCalString: string,
163	): Promise<string> {
164	  try {
165	    const res = await client.createCalendarObject({
166	      calendar: { url: calendarUrl } as DAVCalendar,
167	      iCalString,
168	      filename,
169	    });
170	    if (!res.ok) {
171	      throw new Error(`${res.status} ${res.statusText}`);
172	    }
173	    return objectUrlFor(calendarUrl, filename);
174	  } catch (e) {
175	    throw caldavError(e);
176	  }
177	}
178	
179	/** Replace an existing object's iCalendar body at its href. */
180	export async function putObjectAt(client: DAVClient, url: string, iCalString: string): Promise<void> {
181	  try {
182	    const res = await client.updateCalendarObject({
183	      calendarObject: { url, data: iCalString },
184	    });
185	    if (!res.ok) {
186	      throw new Error(`${res.status} ${res.statusText}`);
187	    }
188	  } catch (e) {
189	    throw caldavError(e);
190	  }
191	}
192	
193	/** Delete an object by its href. */
194	export async function deleteObjectAt(client: DAVClient, url: string): Promise<void> {
195	  try {
196	    const res = await client.deleteCalendarObject({ calendarObject: { url } });
197	    if (!res.ok && res.status !== 404) {
198	      throw new Error(`${res.status} ${res.statusText}`);
199	    }
200	  } catch (e) {
201	    throw caldavError(e);
202	  }
203	}
