    20	export type EnvValidation = { ok: boolean; missing: string[] };
    21	
    22	/**
    23	 * Check that all critical env vars are present and non-empty.
    24	 * Returns `{ ok, missing[] }` and logs a warning (never throws).
    25	 */
    26	export function validateEnv(): EnvValidation {
    27	  const result = envSchema.safeParse(process.env);
    28	  if (result.success) {
    29	    return { ok: true, missing: [] };
    30	  }
    31	  // Collect the top-level keys that failed (missing or empty).
    32	  const missing = Array.from(
    33	    new Set(result.error.issues.map((i) => String(i.path[0])).filter(Boolean)),
    34	  );
    35	  console.warn(
    36	    `[env] Missing or invalid critical environment variables: ${missing.join(", ")}. ` +
