211	/**
212	 * List the mailboxes that really exist on a domain (`GET /get/mailbox/all/<domain>`).
213	 *
214	 * WHY this exists: `resolveMailbox` used to read only `db.mailbox`, so a mailbox
215	 * that lives on Mailcow without a local row was completely invisible in the
216	 * portal — the "it's not detecting the mailbox I already have on this account"
217	 * report. This is the read half of the reconciliation; the adoption half
218	 * (lib/mail/imap.ts `discoverMailboxes`) gates on domain verification.
219	 *
220	 * A domain Mailcow doesn't know returns `{}`, which we normalise to `[]`.
221	 */
222	export async function mcListMailboxes(domain: string): Promise<MailcowMailbox[]> {
223	  const res = await mcRequest("GET", `/get/mailbox/all/${encodeURIComponent(domain)}`);
224	  const rows = Array.isArray(res) ? res : [];
225	  const want = domain.trim().toLowerCase();
226	  const out: MailcowMailbox[] = [];
227	  for (const r of rows) {
228	    if (!r || typeof r !== "object") continue;
229	    const o = r as Record<string, unknown>;
230	    const address = typeof o.username === "string" ? o.username.trim().toLowerCase() : "";
231	    if (!address.includes("@")) continue;
232	    const mboxDomain =
233	      typeof o.domain === "string" ? o.domain.trim().toLowerCase() : address.slice(address.lastIndexOf("@") + 1);
234	    // Never return a row for a different domain than the one asked for — the
235	    // caller uses the domain to decide ownership, so it must not be spoofable
236	    // by a surprising API response shape.
237	    if (mboxDomain !== want) continue;
238	    out.push({
239	      address,
240	      domain: mboxDomain,
241	      name: typeof o.name === "string" ? o.name : "",
242	      active: toActive(o.active),
243	      quotaBytes: Number(o.quota) > 0 ? Number(o.quota) : 0,
244	      quotaUsedBytes: Number(o.quota_used) > 0 ? Number(o.quota_used) : 0,
245	    });
246	  }
247	  return out;
248	}
