333	function toFilterRows(res: unknown): MailcowFilter[] {
334	  const rows = Array.isArray(res) ? res : [];
335	  const out: MailcowFilter[] = [];
336	  for (const r of rows) {
337	    if (!r || typeof r !== "object") continue;
338	    const o = r as Record<string, unknown>;
339	    const id = Number(o.id);
340	    if (!Number.isFinite(id)) continue;
341	    out.push({
342	      id,
343	      username: typeof o.username === "string" ? o.username : "",
344	      scriptDesc: typeof o.script_desc === "string" ? o.script_desc : "",
345	      scriptData: typeof o.script_data === "string" ? o.script_data : "",
346	      filterType: typeof o.filter_type === "string" ? o.filter_type : "",
347	      active: toActive(o.active),
