485	/**
486	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
487	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
488	 * the admin page catches that and shows a graceful fallback.
489	 */
490	export async function mcStats(sample = 400): Promise<MailStats> {
491	  config(); // throws early with a clear message if not configured
492	
493	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
494	    mcRequest("GET", "/get/domain/all").catch(() => []),
495	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
496	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
497	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
498	  ]);
499	
500	  const postfixLogs = asArray(postfixRaw);
501	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
502	  for (const entry of postfixLogs) {
503	    const msg = String(
504	      (entry as { message?: unknown })?.message ??
505	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
506	        "",
507	    ).toLowerCase();
508	    if (msg.includes("status=sent")) postfix.sent++;
509	    else if (msg.includes("status=deferred")) postfix.deferred++;
510	    else if (msg.includes("status=bounced")) postfix.bounced++;
511	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
512	    else postfix.other++;
513	  }
514	
515	  const rspamdLogs = asArray(rspamdRaw);
516	  const actions: Record<string, number> = {};
517	  let spam = 0;
518	  let clean = 0;
519	  for (const entry of rspamdLogs) {
520	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
521	    actions[action] = (actions[action] ?? 0) + 1;
522	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
523	    else clean++;
524	  }
525	
526	  return {
527	    configured: true,
528	    domains: asArray(domainsRaw).length,
529	    mailboxes: asArray(mailboxesRaw).length,
530	    postfix,
531	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
532	  };
533	}
