818	/**
819	 * Store a customer's Cloudflare API token (encrypted) so we can create their
820	 * mail DNS records for them. The token is verified against Cloudflare before it
821	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
822	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
823	 */
824	export async function saveCloudflareToken(token: string): Promise<Result> {
825	  const user = await requireUser();
826	
827	  const t = String(token ?? "").trim();
828	  if (!t) return { error: "Paste your Cloudflare API token." };
829	  if (t.length < 20 || t.length > 200) {
830	    return { error: "That doesn't look like a Cloudflare API token." };
831	  }
832	
833	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
834	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
835	
836	  let valid = false;
837	  try {
838	    valid = await cfVerifyToken(t);
839	  } catch (e) {
840	    console.warn("[cloudflare] token verify failed:", e);
841	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
842	  }
843	  if (!valid) {
844	    return {
845	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
846	    };
847	  }
848	
849	  await db.user.update({
850	    where: { id: user.id },
851	    data: { cloudflareTokenEnc: encryptSecret(t) },
852	  });
853	  await db.auditLog.create({
854	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
855	  });
856	  revalidatePath("/dashboard/email");
857	  return { ok: true };
858	}
