1	// Per-domain mail deliverability self-check (SPF / DKIM / DMARC / MX).
2	//
3	// Plain server-side module (NO "use server") — the ownership-checked server
4	// action lives in lib/actions-email-hosting.ts.
5	//
6	// WHY: customers land in spam with no way to find out why. That is exactly what
7	// happened to the platform owner: mail was silently failing authentication and
8	// the only diagnosis available was an external third-party tool. This gives every
9	// customer a pass/fail per record with the value we ACTUALLY observed next to the
10	// value we expect, so "my mail goes to spam" becomes a fixable DNS row.
11	//
12	// ============================ THE RESOLVER TRAP =============================
13	// This check MUST NOT use the system resolver. This host has:
14	//
15	//     /etc/nsswitch.conf -> hosts: files myhostname dns
16	//
17	// and a populated /etc/hosts. During today's incident a reverse lookup returned a
18	// value straight out of that local text file while appearing to have asked
19	// Cloudflare and Google — which produced a completely confident, completely wrong
20	// diagnosis. A customer-facing check built on the system resolver would tell
21	// people their DNS is broken when it is fine, or the reverse.
22	//
23	// So: resolve the zone's NS records through PINNED public resolvers, resolve
24	// those nameservers to IPs, then query THOSE nameservers directly for every
25	// record. The answer then comes from the zone's own authority — no /etc/hosts, no
26	// inherited /etc/resolv.conf, no recursive-cache staleness after the customer
27	// has just fixed a record.
28	// ============================================================================
29	
30	import { Resolver } from "node:dns/promises";
31	
32	/** Public resolvers used ONLY to find the zone's nameservers. Never the OS list. */
33	const BOOTSTRAP_RESOLVERS = ["1.1.1.1", "8.8.8.8", "9.9.9.9"];
34	
35	const DNS_TIMEOUT_MS = 4000;
36	const DNS_TRIES = 2;
37	
38	export type CheckStatus = "pass" | "warn" | "fail" | "unknown";
39	
40	export type DeliverabilityCheck = {
41	  key: "mx" | "spf" | "dkim" | "dmarc";
42	  label: string;
43	  status: CheckStatus;
44	  /** What the authoritative nameservers actually returned (empty = nothing published). */
45	  observed: string;
46	  /** What we need to see there. */
47	  expected: string;
48	  /** One line the customer can act on. */
49	  detail: string;
50	  /** The DNS name that was queried, so the customer knows which row to edit. */
51	  host: string;
52	  type: "MX" | "TXT";
53	};
54	
55	export type DeliverabilityReport = {
56	  domain: string;
57	  /** The authoritative nameservers we queried — shown so the result is auditable. */
58	  nameservers: string[];
59	  checks: DeliverabilityCheck[];
60	  /** Set when we could not establish authority at all (checks will be `unknown`). */
61	  error?: string;
62	  checkedAt: string;
63	};
64	
65	function bootstrapResolver(): Resolver {
66	  const r = new Resolver({ timeout: DNS_TIMEOUT_MS, tries: DNS_TRIES });
67	  // Explicit setServers is the entire point — a bare `new Resolver()` inherits
68	  // /etc/resolv.conf, which is the failure mode described at the top of this file.
69	  r.setServers(BOOTSTRAP_RESOLVERS);
70	  return r;
71	}
72	
73	/** All parent zones of a name, apex last: a.b.example.com -> b.example.com, example.com. */
74	function parentZones(domain: string): string[] {
75	  const labels = domain.split(".").filter(Boolean);
76	  const out: string[] = [];
77	  for (let i = 0; i < labels.length - 1; i++) out.push(labels.slice(i).join("."));
78	  return out;
79	}
80	
81	/**
82	 * Find the zone's authoritative nameservers and return a Resolver pinned to them.
83	 *
84	 * Walks up from the queried name because a mail domain can be a subdomain whose
85	 * NS records live on the parent zone; without the walk a perfectly healthy
86	 * `mail.customer.com` would report "we can't find your nameservers".
87	 */
88	async function authoritativeResolver(
89	  domain: string,
90	): Promise<{ resolver: Resolver; nameservers: string[] } | { error: string }> {
91	  const boot = bootstrapResolver();
92	
93	  let nameservers: string[] = [];
94	  for (const zone of [domain, ...parentZones(domain)]) {
95	    try {
96	      const ns = await boot.resolveNs(zone);
97	      if (ns.length > 0) {
98	        nameservers = ns.map((n) => n.replace(/\.$/, "").toLowerCase());
99	        break;
100	      }
101	    } catch {
102	      // NXDOMAIN / ENODATA at this level — try the parent zone.
103	    }
104	  }
105	  if (nameservers.length === 0) {
106	    return { error: "No nameservers found for this domain — check it is registered and delegated." };
107	  }
108	
109	  const ips: string[] = [];
110	  for (const ns of nameservers) {
111	    const [v4, v6] = await Promise.all([
112	      boot.resolve4(ns).catch(() => [] as string[]),
113	      boot.resolve6(ns).catch(() => [] as string[]),
114	    ]);
115	    ips.push(...v4, ...v6);
116	  }
117	  if (ips.length === 0) {
118	    return { error: `Could not resolve this domain's nameservers (${nameservers.join(", ")}) to an address.` };
119	  }
120	
121	  const resolver = new Resolver({ timeout: DNS_TIMEOUT_MS, tries: DNS_TRIES });
122	  resolver.setServers(ips);
123	  return { resolver, nameservers };
124	}
125	
126	/** A TXT record's chunks are concatenated with NO separator (RFC 7208 §3.3). */
127	function joinTxt(record: string[]): string {
128	  return record.join("").trim();
129	}
130	
131	async function txtAt(resolver: Resolver, host: string): Promise<string[] | null> {
132	  try {
133	    return (await resolver.resolveTxt(host)).map(joinTxt).filter(Boolean);
134	  } catch {
135	    // NXDOMAIN / ENODATA from the authority means "not published".
136	    return null;
137	  }
138	}
139	
140	/** Normalise a DKIM TXT value so cosmetic differences don't read as a mismatch. */
141	function dkimKey(value: string): string {
142	  const m = value.match(/(?:^|[;\s])p=([A-Za-z0-9+/=]*)/);
143	  return m ? m[1] : "";
144	}
145	
146	function truncate(v: string, max = 180): string {
147	  return v.length > max ? `${v.slice(0, max)}…` : v;
148	}
149	
150	/**
151	 * Run the four authentication checks for `domain`.
152	 *
153	 * `mailHost` is the MX we expect, `spfInclude` the mechanism that authorises our
154	 * sending host, and `dkim` MUST be the LIVE key read from Mailcow
155	 * (`GET /get/dkim/<domain>` → `dkim_txt`), never the cached
156	 * `EmailSubscription.dkimRecord`: a stale cache would confirm a key that no
157	 * longer signs anything.
158	 */
159	export async function checkDeliverability(opts: {
160	  domain: string;
161	  mailHost: string;
162	  spfInclude: string;
163	  spfExpected: string;
164	  dmarcExpected: string;
165	  dkim: { selector: string; txt: string } | null;
166	}): Promise<DeliverabilityReport> {
167	  const domain = opts.domain.trim().toLowerCase().replace(/\.$/, "");
168	  const checkedAt = new Date().toISOString();
169	  const dkimSelector = opts.dkim?.selector || "dkim";
170	  const dkimHost = `${dkimSelector}._domainkey.${domain}`;
171	
172	  const auth = await authoritativeResolver(domain);
173	  if ("error" in auth) {
174	    const unknown = (
175	      key: DeliverabilityCheck["key"],
176	      label: string,
177	      host: string,
178	      type: DeliverabilityCheck["type"],
179	      expected: string,
180	    ): DeliverabilityCheck => ({
181	      key,
182	      label,
183	      status: "unknown",
184	      observed: "",
185	      expected,
186	      detail: "Couldn't reach this domain's nameservers to read the record.",
187	      host,
188	      type,
189	    });
190	    return {
191	      domain,
192	      nameservers: [],
193	      error: auth.error,
194	      checkedAt,
195	      checks: [
196	        unknown("mx", "MX — mail routing", domain, "MX", `${opts.mailHost} (priority 10)`),
197	        unknown("spf", "SPF — authorised senders", domain, "TXT", opts.spfExpected),
198	        unknown("dkim", "DKIM — message signing", dkimHost, "TXT", opts.dkim?.txt ?? "(no key on the mail server yet)"),
199	        unknown("dmarc", "DMARC — policy", `_dmarc.${domain}`, "TXT", opts.dmarcExpected),
200	      ],
201	    };
202	  }
203	
204	  const { resolver, nameservers } = auth;
205	
206	  const [mxRecords, apexTxt, dkimTxt, dmarcTxt] = await Promise.all([
207	    resolver.resolveMx(domain).catch(() => null),
208	    txtAt(resolver, domain),
209	    txtAt(resolver, dkimHost),
210	    txtAt(resolver, `_dmarc.${domain}`),
211	  ]);
212	
213	  const checks: DeliverabilityCheck[] = [];
214	
215	  // ---- MX ----------------------------------------------------------------
216	  {
217	    const rows = (mxRecords ?? []).map((r) => ({
218	      exchange: r.exchange.replace(/\.$/, "").toLowerCase(),
219	      priority: r.priority,
220	    }));
221	    const observed = rows.length
222	      ? rows
223	          .slice()
224	          .sort((a, b) => a.priority - b.priority)
225	          .map((r) => `${r.exchange} (${r.priority})`)
226	          .join(", ")
227	      : "";
228	    const ours = rows.some((r) => r.exchange === opts.mailHost);
229	    checks.push({
230	      key: "mx",
231	      label: "MX — mail routing",
232	      status: ours ? (rows.length > 1 ? "warn" : "pass") : rows.length ? "fail" : "fail",
233	      observed,
234	      expected: `${opts.mailHost} (priority 10)`,
235	      host: domain,
236	      type: "MX",
237	      detail: !rows.length
238	        ? "No MX record published — inbound mail for this domain has nowhere to go."
239	        : ours
240	          ? rows.length > 1
241	            ? "Our mail host is listed, but so are others — mail may be delivered to a different server."
242	            : "Inbound mail is routed to the Nxeon mail server."
243	          : `Mail is routed elsewhere. Point the MX at ${opts.mailHost} or inbound mail will never reach these mailboxes.`,
244	    });
245	  }
246	
247	  // ---- SPF ---------------------------------------------------------------
248	  {
249	    const spfRecords = (apexTxt ?? []).filter((t) => /^v=spf1\b/i.test(t));
250	    const observed = spfRecords.join(" | ");
251	    let status: CheckStatus = "fail";
252	    let detail: string;
253	    if (spfRecords.length === 0) {
254	      detail = "No SPF record published — receivers have nothing authorising us to send for you.";
255	    } else if (spfRecords.length > 1) {
256	      status = "fail";
257	      detail = "More than one SPF record. RFC 7208 makes that a permanent error — merge them into one.";
258	    } else {
259	      const spf = spfRecords[0];
260	      const authorised =
261	        spf.toLowerCase().includes(`include:${opts.spfInclude}`) ||
262	        // `mx` authorises whatever the MX points at, which is our mail host when
263	        // the MX check above passes — a valid, commonly-used alternative.
264	        /(?:^|\s)mx(?:\s|$)/i.test(spf);
265	      if (authorised) {
266	        status = /[~-]all\s*$/.test(spf) ? "pass" : "warn";
267	        detail =
268	          status === "pass"
269	            ? "The Nxeon mail server is authorised to send for this domain."
270	            : "Authorised, but the record has no `~all`/`-all` terminator, so receivers apply no policy to unauthorised senders.";
271	      } else {
272	        detail = `SPF exists but doesn't authorise us. Add \`include:${opts.spfInclude}\` (or \`mx\`) or your mail will be treated as spoofed.`;
273	      }
274	    }
275	    checks.push({
276	      key: "spf",
277	      label: "SPF — authorised senders",
278	      status,
279	      observed,
280	      expected: opts.spfExpected,
281	      host: domain,
282	      type: "TXT",
283	      detail,
284	    });
285	  }
286	
287	  // ---- DKIM --------------------------------------------------------------
288	  {
289	    const published = (dkimTxt ?? []).find((t) => /(?:^|[;\s])p=/.test(t)) ?? "";
290	    const expected = opts.dkim?.txt ?? "";
291	    let status: CheckStatus = "fail";
292	    let detail: string;
293	    if (!expected) {
294	      status = "unknown";
295	      detail =
296	        "The mail server hasn't generated a DKIM key for this domain yet — there is nothing to publish. Reload in a moment.";
297	    } else if (!published) {
298	      detail = `No DKIM record at ${dkimHost}. Without it every message you send is unsigned, which is the single biggest reason mail lands in spam.`;
299	    } else if (dkimKey(published) && dkimKey(published) === dkimKey(expected)) {
300	      status = "pass";
301	      detail = `Published key matches the one the mail server signs with (selector \`${dkimSelector}\`).`;
302	    } else {
303	      detail =
304	        "A DKIM record exists but the public key does not match the mail server's current key — signatures will fail. Replace it with the value shown here.";
305	    }
306	    checks.push({
307	      key: "dkim",
