32	/** True if an IPv4 address sits in a range we refuse to connect to. */
33	function isBlockedIpv4(ip: string): boolean {
34	  const oct = ipv4Octets(ip);
35	  if (!oct) return false;
36	  const [a, b] = oct;
37	  if (a === 0) return true; // 0.0.0.0/8 "this network"
38	  if (a === 127) return true; // loopback 127.0.0.0/8
39	  if (a === 10) return true; // private 10.0.0.0/8
40	  if (a === 172 && b >= 16 && b <= 31) return true; // private 172.16.0.0/12
41	  if (a === 192 && b === 168) return true; // private 192.168.0.0/16
42	  if (a === 169 && b === 254) return true; // link-local 169.254.0.0/16 (AWS metadata)
43	  if (a === 100 && b >= 64 && b <= 127) return true; // CGNAT 100.64.0.0/10
44	  if (a === 192 && b === 0 && oct[2] === 0) return true; // 192.0.0.0/24 IETF
45	  if (a === 192 && b === 0 && oct[2] === 2) return true; // TEST-NET-1 192.0.2.0/24
46	  if (a >= 224) return true; // multicast + reserved 224.0.0.0/3
47	  return false;
48	}
