217	/**
218	 * Reissue a certificate now (owner only), for an ACTIVE/EXPIRED/FAILED row.
219	 *
220	 * Shares the weekly counter with requestCertificate and the worker's renewal
221	 * sweep, so a customer hammering this button cannot exhaust Let's Encrypt's
222	 * duplicate-certificate limit.
223	 */
224	export async function renewCertificate(id: string): Promise<{ error?: string }> {
225	  let ctx;
226	  try {
227	    ctx = await ownedCertificate(id);
228	  } catch (e: any) {
229	    return { error: e.message };
230	  }
231	  const { user, cert } = ctx;
232	
233	  if (!["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status)) {
234	    return { error: "This certificate is already being worked on — wait for the current attempt to finish." };
235	  }
236	  if (!cert.serverId) {
237	    return { error: "This certificate is not attached to a server, so it cannot be issued." };
238	  }
239	  if (await liveIssueJob(cert.id)) {
240	    return { error: "An issue job for this certificate is already queued." };
241	  }
242	
243	  const rate = await issueAttemptsFor(cert.domain);
244	  if (rateLimited(rate)) return { error: rateLimitMessage(cert.domain, rate) };
245	
246	  // One in-flight job per server, matching the worker's own invariant.
247	  const busy = await db.job.count({
248	    where: { serverId: cert.serverId, status: { in: ["QUEUED", "RUNNING"] } },
249	  });
250	  if (busy > 0) {
251	    return {
252	      error:
253	        "Another operation is already queued for this server. The platform runs one job at a time — try again once it finishes.",
254	    };
255	  }
256	
257	  await db.job.create({
258	    data: {
259	      type: "SSL_ISSUE",
260	      serverId: cert.serverId,
261	      // `renewal: true` keeps a still-valid certificate ACTIVE if the reissue
262	      // fails, instead of flipping a working site's row to FAILED.
263	      payload: { certId: cert.id, domain: cert.domain, renewal: true },
264	    },
265	  });
266	  await db.auditLog.create({
267	    data: { userId: user.id, action: "ssl.renew", detail: `${cert.domain}` },
268	  });
269	  revalidatePath("/dashboard/ssl");
270	  return {};
271	}
