292	/**
293	 * Read the certificate's REAL notAfter off the customer's VM.
294	 *
295	 * There is deliberately no fallback. The previous version defaulted to
296	 * `now + 90 days` whenever `openssl x509 -enddate` could not be parsed, which is
297	 * how a row could claim ACTIVE with an expiry nobody had ever observed — the same
298	 * class of lie as the simulated-success branch. If we cannot read the date, the
299	 * attempt is a failure and says so; re-requesting is cheap because certbot reuses
300	 * a still-valid certificate without asking Let's Encrypt again.
301	 */
302	async function readObservedExpiry(conn: SshClient, domain: string): Promise<Date> {
303	  const live = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
304	  const enddate = await sshExec(
305	    conn,
306	    `openssl x509 -enddate -noout -in ${shellQuote(live)} 2>&1 || true`,
307	    PROBE_TIMEOUT_MS
308	  );
309	  const m = enddate.stdout.match(/notAfter=(.+)/);
310	  const parsed = m ? new Date(m[1].trim()) : null;
311	  if (!parsed || Number.isNaN(parsed.getTime())) {
312	    throw new Error(
313	      `certbot reported success but the certificate's real expiry could not be read back from ${live} ` +
314	        `(${(enddate.stdout || "no output").trim().slice(0, 160)}). We do not report a certificate as ` +
315	        `active on a guessed expiry date, so this attempt is recorded as failed. Requesting again is safe.`
316	    );
317	  }
318	  return parsed;
319	}
