439	// ----------------------------------------------------------------------------
440	// Read back what is actually being served (no SSH, no certbot, no ACME).
441	// ----------------------------------------------------------------------------
442	
443	type ServedCert =
444	  | { ok: true; notAfter: Date; coversDomain: boolean }
445	  | { ok: false; reason: string };
446	
447	function tlsErrorReason(e: any): string {
448	  const code = String(e?.code ?? "");
449	  if (code === "ECONNREFUSED") return "nothing is listening on port 443";
450	  if (code === "ENOTFOUND" || code === "EAI_AGAIN") return "the domain does not resolve in DNS";
451	  if (code === "ETIMEDOUT") return "the connection to port 443 timed out";
452	  if (code === "ECONNRESET") return "the connection was reset before TLS finished";
453	  if (code === "EHOSTUNREACH" || code === "ENETUNREACH") return "the host is unreachable";
454	  return (String(e?.message ?? e) || code || "the TLS connection failed").slice(0, 140);
455	}
456	
457	/** Does a certificate name (possibly `*.example.com`) cover `domain`? */
458	function hostMatches(name: string, domain: string): boolean {
459	  const n = name.trim().toLowerCase();

460	  const d = domain.trim().toLowerCase();
461	  if (!n) return false;
462	  if (n === d) return true;
463	  if (n.startsWith("*.")) {
464	    // A wildcard covers exactly one label, so the label counts must match.
465	    return d.endsWith(n.slice(1)) && d.split(".").length === n.split(".").length;
466	  }
467	  return false;
468	}
