470	/**
471	 * Open a plain TLS connection to `domain:443` and read the certificate the
472	 * public internet is actually being handed.
473	 *
474	 * This is the cheap, honest half of "is it really active": certbot --standalone
475	 * OBTAINS a certificate but does not install it into nginx/apache, so
476	 * issued-and-not-served is the normal outcome, not an edge case. Reading it back
477	 * is the only way the dashboard can tell the difference — and it costs one
478	 * handshake to a public hostname, no SSH and no ACME.
479	 *
480	 * `rejectUnauthorized: false` is deliberate: an expired, self-signed or
481	 * wrong-name certificate is exactly the state the customer needs to be told
482	 * about, and refusing the handshake would throw that information away. Nothing
483	 * is ever sent over this socket.
484	 */
485	function probeServedCertificate(domain: string): Promise<ServedCert> {
486	  return new Promise((resolve) => {
487	    let settled = false;
488	    let socket: ReturnType<typeof tlsConnect> | null = null;
489	    const done = (r: ServedCert) => {
490	      if (settled) return;
491	      settled = true;
492	      try {
493	        socket?.destroy();
494	      } catch {
495	        /* best effort */
496	      }
497	      resolve(r);
498	    };
499	
500	    try {
501	      socket = tlsConnect(
502	        {
503	          host: domain,
504	          port: 443,
505	          servername: domain,
506	          rejectUnauthorized: false,
507	        },
508	        () => {
509	          try {
510	            const peer = socket!.getPeerCertificate();
511	            if (!peer || !peer.valid_to) {
512	              return done({ ok: false, reason: "the server presented no certificate" });
513	            }
514	            const notAfter = new Date(peer.valid_to);
515	            if (Number.isNaN(notAfter.getTime())) {
516	              return done({ ok: false, reason: `its expiry date was unreadable (${peer.valid_to})` });
517	            }
518	            const names: string[] = [];
519	            if (peer.subject?.CN) names.push(String(peer.subject.CN));
520	            for (const entry of String(peer.subjectaltname ?? "").split(",")) {
521	              const t = entry.trim();
522	              if (t.toLowerCase().startsWith("dns:")) names.push(t.slice(4));
523	            }
524	            done({ ok: true, notAfter, coversDomain: names.some((n) => hostMatches(n, domain)) });
525	          } catch (e: any) {
526	            done({ ok: false, reason: String(e?.message ?? e).slice(0, 140) });
527	          }
528	        }
529	      );
530	      // Idle timeout covers the connect phase too, so a black-holed host cannot
531	      // hold the serial worker loop open.
532	      socket.setTimeout(TLS_PROBE_TIMEOUT_MS, () =>
533	        done({ ok: false, reason: `port 443 did not respond within ${Math.round(TLS_PROBE_TIMEOUT_MS / 1000)}s` })
534	      );
535	      socket.on("error", (e: any) => done({ ok: false, reason: tlsErrorReason(e) }));
536	    } catch (e: any) {
537	      done({ ok: false, reason: tlsErrorReason(e) });
538	    }
539	  });
540	}
