542	// Deterministic warning texts. They are compared for equality below so a sweep
543	// can recognise a note it wrote itself and avoid overwriting a real error.
544	function notServedWarning(domain: string, reason: string): string {
545	  return (
546	    `The certificate exists, but nothing is serving it for https://${domain} — ${reason}. ` +
547	    `certbot obtains the certificate in standalone mode; it does not install it into your web server. ` +
548	    `Point your TLS config at /etc/letsencrypt/live/${domain}/fullchain.pem and privkey.pem, then reload it.`
549	  );
