565	/**
566	 * Make a row match the certificate the internet can actually see, and return the
567	 * expiry we now believe (observed if we could read one).
568	 *
569	 * This is where "honest status" is enforced: `expiresAt` becomes the observed
570	 * notAfter, an out-of-band renewal (certbot installs its own systemd timer on the
571	 * VM, so certificates do renew without us) is picked up instead of triggering a
572	 * pointless reissue, and an issued-but-not-installed certificate gets a visible
573	 * note instead of a silent green dot.
574	 */
575	async function verifyServed(cert: SslCertificate): Promise<Date | null> {
576	  const served = await probeServedCertificate(cert.domain);
577	  const now = Date.now();
578	
579	  if (served.ok && served.coversDomain) {
580	    const status = served.notAfter.getTime() > now ? "ACTIVE" : "EXPIRED";
581	    // A valid certificate on the wire is proof the row is healthy, so any stale
582	    // renewal error is cleared here rather than nagging forever.
583	    const lastError =
584	      status === "ACTIVE"
585	        ? null
586	        : `The certificate being served for ${cert.domain} expired on ${served.notAfter
587	            .toISOString()
588	            .slice(0, 10)}. Visitors see a browser security warning until a new one is installed.`;
589	    const changed =
590	      cert.status !== status ||
591	      cert.expiresAt?.getTime() !== served.notAfter.getTime() ||
592	      cert.lastError !== lastError;
593	    if (changed) {
594	      await db.sslCertificate.update({
595	        where: { id: cert.id },
596	        data: { status, expiresAt: served.notAfter, lastError },
597	      });
598	    }
599	    return served.notAfter;
600	  }
601	
602	  // Could not confirm a matching certificate on the wire. Keep the issuer-read
603	  // expiry (it is still the best observed value we have) but say so — and never
604	  // clobber a genuine renewal/issuance error with a probe note.
605	  const note = served.ok ? wrongNameWarning(cert.domain) : notServedWarning(cert.domain, served.reason);
606	  if ((cert.lastError === null || isProbeWarning(cert.lastError)) && cert.lastError !== note) {
607	    await db.sslCertificate.update({ where: { id: cert.id }, data: { lastError: note } });
608	  }
609	  return cert.expiresAt;
610	}
