622	export async function sslIssue(job: Job): Promise<void> {
623	  const payload = payloadOf(job);
624	  if (!payload.certId) throw new Error("ssl job: missing certId");
625	  const isRenewal = payload.renewal === true;
626	
627	  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
628	  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);
629	
630	  /** Record the outcome on the job so the rate-limit counter can classify it. */
631	  const markStep = async (step: string) => {
632	    await db.job.update({ where: { id: job.id }, data: { step } }).catch(() => {
633	      /* the outcome marker is an optimisation; never fail the job over it */
634	    });
635	  };
636	
637	  // Mark in-flight so the UI shows "issuing" while we work. On a renewal the row
638	  // keeps its existing expiresAt, so the dashboard can still say "current
639	  // certificate valid until <date>" instead of implying the site is down.
640	  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });
641	
642	  const phase: IssuePhase = { reachedAcme: false };
643	
644	  try {
645	    // ---------------------------------------------------------------------
646	    // Real issuance path (SSH + certbot). Guarded so it can never run by
647	    // accident: it happens ONLY when ENABLE_REAL_SSL is explicitly set AND we
648	    // are not in SANDBOX.
649	    // ---------------------------------------------------------------------
650	    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
651	    if (realIssuanceEnabled) {
652	      const { issuedAt, expiresAt } = await issueRealCertificate(cert, phase);
653	
654	      // Immediately read back what the domain actually serves. certbot
655	      // --standalone does NOT wire the certificate into nginx/apache, so the
656	      // common outcome of a successful issue is "obtained but not installed" —
657	      // telling the customer their site is now HTTPS would be wrong.
658	      let installNote: string | null = null;
659	      if (!SANDBOX) {
660	        const served = await probeServedCertificate(cert.domain);
661	        if (!served.ok) installNote = notServedWarning(cert.domain, served.reason);
662	        else if (!served.coversDomain) installNote = wrongNameWarning(cert.domain);
663	      }
664	
665	      await db.sslCertificate.update({
666	        where: { id: cert.id },
667	        data: { status: "ACTIVE", issuedAt, expiresAt, lastError: installNote },
668	      });
669	      await markStep(SSL_STEP_ISSUED);
670	      await notify(
671	        cert.userId,
672	        `SSL certificate ${isRenewal ? "renewed" : "issued"} for ${cert.domain}`,
673	        installNote
674	          ? `Obtained, valid until ${expiresAt.toISOString().slice(0, 10)} — but not yet installed in your web server.`
675	          : `Verified live on https://${cert.domain}, valid until ${expiresAt.toISOString().slice(0, 10)}.`,
676	        "/dashboard/ssl"
677	      );
678	      return;
679	    }
680	
681	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
682	    //
683	    // Until 2026-07-25 it did: production has no ENABLE_REAL_SSL, so every real
684	    // customer request fell through to the block below, which wrote status
685	    // "ACTIVE" with an invented 90-day expiry and told them "your Let's Encrypt
686	    // certificate is active" — while no certbot had run and no certificate
687	    // existed. Identical in kind to the migration reporting "Sites serving: 4/4"
688	    // with six domains dark: the system asserting an outcome it never verified.
689	    //
690	    // A certificate we did not issue is a FAILURE, and it must say so loudly
691	    // enough that an operator notices the flag is missing.
692	    if (!SANDBOX) {
693	      throw new Error(
694	        "Certificate issuance is switched off on this server (ENABLE_REAL_SSL is not set), " +
695	          "so no certificate was requested from Let's Encrypt. Nothing was installed — " +
696	          "this certificate is NOT active. Ask support to enable real issuance."
697	      );
698	    }
699	
700	    // Default: simulated success (SANDBOX-only, no SSH, no certbot).
701	    const now = new Date();
702	    await db.sslCertificate.update({
703	      where: { id: cert.id },
704	      data: {
705	        status: "ACTIVE",
706	        issuedAt: now,
707	        expiresAt: new Date(now.getTime() + SANDBOX_CERT_LIFETIME_MS),
708	        lastError: null,
709	      },
710	    });
711	    await markStep(SSL_STEP_SANDBOX);
712	    await notify(
713	      cert.userId,
714	      `SSL certificate ${isRenewal ? "renewed" : "issued"} for ${cert.domain}`,
715	      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
716	      "/dashboard/ssl"
717	    );
718	  } catch (e: any) {
719	    const reason = String(e?.message ?? e).slice(0, 500);
720	
721	    // A failed RENEWAL must not erase the fact that the current certificate is
722	    // still serving traffic. Flipping a cert with 20 valid days left to FAILED is
723	    // its own kind of lie — it would panic a customer whose site is fine.
724	    //
725	    // `cert` was read before this attempt set ISSUING, so cert.status is the
726	    // pre-attempt status: only a row that really was live can come back as
727	    // ACTIVE/EXPIRED. A reissue of a FAILED row that fails again stays FAILED, so
728	    // a retry can never launder a row into looking like it once worked.
729	    const wasLive = cert.status === "ACTIVE" || cert.status === "EXPIRED";
730	    let status: string;
731	    if (isRenewal && wasLive && cert.expiresAt && cert.expiresAt.getTime() > Date.now()) {
732	      status = "ACTIVE";
733	    } else if (isRenewal && wasLive) {
734	      status = "EXPIRED";
735	    } else {
736	      status = "FAILED";
737	    }
738	
739	    const detail = isRenewal ? `Renewal failed: ${reason}`.slice(0, 500) : reason;
740	    await db.sslCertificate.update({
741	      where: { id: cert.id },
742	      data: { status, lastError: detail },
743	    });
744	    await markStep(phase.reachedAcme ? SSL_STEP_ACME_FAILED : SSL_STEP_PREFLIGHT_FAILED);
745	    await notify(
746	      cert.userId,
747	      `SSL certificate ${isRenewal ? "renewal" : "request"} failed for ${cert.domain}`,
748	      detail.slice(0, 200),
749	      "/dashboard/ssl"
750	    );
751	  }
752	}
