754	// ----------------------------------------------------------------------------
755	// Lifecycle sweep: reconcile stalled/expired rows, then renew what is due.
756	// ----------------------------------------------------------------------------
757	
758	type Attempt = {
759	  /** Every attempt, including ones that never reached the ACME server. */

758	type Attempt = {
759	  /** Every attempt, including ones that never reached the ACME server. */
760	  total: number;
761	  /** Attempts that may have consumed a Let's Encrypt duplicate-cert slot. */
762	  leRelevant: number;
763	  lastAt: Date;
764	};
765	
766	/**
767	 * Whether an SSL_ISSUE attempt should be counted against the Let's Encrypt
768	 * weekly limit. Attempts that died locally (no certbot, port 80 busy, SSH
769	 * refused) never reached the ACME server and must NOT count — otherwise a
770	 * customer with a busy port 80 gets locked out of certificates for a week by
771	 * failures Let's Encrypt never saw. `null` (in flight, or a legacy row) counts:
772	 * when in doubt, protect the limit.
773	 */
774	function attemptCountsAgainstLimit(step: string | null): boolean {
775	  return step !== SSL_STEP_PREFLIGHT_FAILED && step !== SSL_STEP_SANDBOX;
776	}
777	
778	/**
779	 * Issue attempts in the current window, keyed by DOMAIN — not by certificate id.
780	 *
781	 * The key matters: Let's Encrypt's duplicate-certificate limit is per identical
782	 * hostname set, and deleting a row and requesting it again mints a fresh certId.
783	 * A per-certId counter would therefore reset on every delete/re-request, letting
784	 * a frustrated customer burn all five weekly slots in minutes and lose HTTPS for
785	 * a week.
786	 */
787	async function loadIssueHistory(): Promise<Map<string, Attempt>> {
788	  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
789	  const jobs = await db.job.findMany({
790	    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
791	    select: { payload: true, step: true, createdAt: true },
792	    orderBy: { createdAt: "asc" },
793	  });
794	  const map = new Map<string, Attempt>();
795	  for (const j of jobs) {
796	    const domain = payloadOf(j).domain;
797	    if (!domain) continue; // pre-2026-07-26 jobs carried only certId
798	    const prev = map.get(domain);
799	    map.set(domain, {
800	      total: (prev?.total ?? 0) + 1,
801	      leRelevant: (prev?.leRelevant ?? 0) + (attemptCountsAgainstLimit(j.step) ? 1 : 0),
802	      lastAt: j.createdAt,
803	    });
804	  }
805	  return map;
806	}
