929	export async function sslRenewalSweep(): Promise<void> {
930	  const now = Date.now();
931	  const dueBefore = new Date(now + RENEW_LEAD_MS);
932	
933	  const candidates = await db.sslCertificate.findMany({
934	    where: {
935	      OR: [
936	        { status: "ACTIVE", expiresAt: { lt: dueBefore } },
937	        // No observed expiry at all: we cannot prove this is valid, so treat it
938	        // as needing verification/reissue (still subject to every cap below).
939	        { status: "ACTIVE", expiresAt: null },
940	        { status: "EXPIRED" },
941	      ],
942	    },
943	    orderBy: [{ expiresAt: "asc" }],
944	    take: MAX_CERTS_PER_SWEEP,
945	  });
946	  if (candidates.length === 0) return;
947	
948	  const live = await loadLiveIssueJobs();
949	  const history = await loadIssueHistory();
950	  const probeDeadline = now + PROBE_BUDGET_MS;
951	  let enqueued = 0;
952	
953	  for (const cert of candidates) {
954	    // Never stack a second issue job on a certificate already being worked.
955	    if (live.has(cert.id)) continue;
956	
957	    let expiresAt = cert.expiresAt;
958	    let fresh = cert;
959	    if (!SANDBOX && Date.now() < probeDeadline) {
960	      // Sandbox domains are fictional, so the probe would only ever produce a
961	      // scary "nothing is serving this" note there.
962	      expiresAt = await verifyServed(cert);
963	      const reloaded = await db.sslCertificate.findUnique({ where: { id: cert.id } });
964	      if (!reloaded) continue;
965	      fresh = reloaded;
966	    }
967	
968	    // Re-evaluate against the observed expiry, not the one we started with.
969	    const due = !expiresAt || expiresAt.getTime() - Date.now() <= RENEW_LEAD_MS;
970	    if (!due) continue;
971	
972	    if (!fresh.autoRenew) {
973	      // The switch is no longer decoration: off means we really do nothing, so
974	      // the customer has to be told before the site breaks.
975	      const when = expiresAt ? expiresAt.toISOString().slice(0, 10) : "an unknown date";
976	      await notifyOnce(
977	        fresh.userId,
978	        `SSL certificate for ${fresh.domain} needs renewing`,
979	        `Auto-renew is switched off for this certificate. It expires on ${when} and will not be replaced ` +
980	          `automatically — turn auto-renew on, or renew it yourself, before then.`,
981	        3 * 86400_000
982	      );
983	      continue;
984	    }
985	
986	    const hist = history.get(fresh.domain);
987	    const total = hist?.total ?? 0;
988	    const leRelevant = hist?.leRelevant ?? 0;
989	
990	    if (leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW || total >= MAX_TOTAL_ATTEMPTS_PER_WINDOW) {
991	      // Stop, visibly. The LE arm stops one slot short of the weekly limit; the
992	      // total arm stops a permanently-broken server being retried forever.
993	      const resumesAt = new Date((hist?.lastAt.getTime() ?? now) + ISSUE_WINDOW_MS);
994	      const why =
995	        leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW
996	          ? `${leRelevant} certificate requests for ${fresh.domain} have reached Let's Encrypt in the last 7 days. ` +
997	            `Let's Encrypt allows only 5 identical certificates per week, so we stop short of the limit rather ` +
998	            `than lock you out of HTTPS entirely.`
999	          : `${total} renewal attempts for ${fresh.domain} have failed in the last 7 days without reaching ` +
1000	            `Let's Encrypt, so retrying again would just fail the same way.`;
1001	      const note =
1002	        `${RENEWAL_PAUSED_PREFIX} until ${resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC: ` +
1003	        `${why} Fix the cause below, then renewal resumes on its own.` +
1004	        (fresh.lastError && !fresh.lastError.startsWith(RENEWAL_PAUSED_PREFIX)
1005	          ? ` Last error: ${fresh.lastError.slice(0, 160)}`
1006	          : "");
1007	      if (fresh.lastError !== note) {
1008	        await db.sslCertificate.update({
1009	          where: { id: fresh.id },
1010	          data: { lastError: note.slice(0, 500) },
1011	        });
1012	      }
1013	      await notifyOnce(
1014	        fresh.userId,
1015	        `SSL renewal paused for ${fresh.domain}`,
1016	        note.slice(0, 200),
1017	        3 * 86400_000
1018	      );
1019	      continue;
1020	    }
1021	
1022	    // Escalating backoff keyed on TOTAL attempts — see RENEW_BACKOFF_MS. This is
1023	    // the guard that makes a 30-minute sweep incapable of becoming a retry loop.
1024	    const wait = RENEW_BACKOFF_MS[Math.min(total, RENEW_BACKOFF_MS.length - 1)];
1025	    if (hist && Date.now() - hist.lastAt.getTime() < wait) continue;
1026	
1027	    // Respect the platform's one-in-flight-job-per-server invariant (same as
1028	    // scheduledBackupSweep) so a renewal never queues behind its own siblings.
1029	    if (fresh.serverId) {
1030	      const busy = await db.job.count({
1031	        where: { serverId: fresh.serverId, status: { in: ["QUEUED", "RUNNING"] } },
1032	      });
